    expect(round.attempts).toHaveLength(2);
    expect(authored.I15_REVISION_MANIFEST.attemptsPerReturnedNode).toBe(1);
    let count = 0;
    for (const review of round.reviewInput.records) {
      for (const category of ["clarityIssues", "cues", "fairness", "suggestions"] as const) {
        for (const [index, note] of review[category].entries()) {
          count += 1;
          const responses = round.noteResponses.filter(r => r.nodeId === review.nodeId && r.category === category && r.index === index);
          expect(responses).toHaveLength(1);
          expect(responses[0]!.note).toEqual(note);
