        }
      }
      const beforeCase = round.reviewedSnapshot.I15_CASES.find(c => c.id === review.id)!;
      const beforeNode = beforeCase.decisionNodes.find(n => n.id === review.nodeId)!;
      const current = authored.I15_QUESTIONS.find(q => q.id === beforeNode.questionVariantId)!;
