        expect(attempt.beforeQuestionSha256).toBe(sha(round.reviewedSnapshot.I15_QUESTIONS.find(q => q.id === beforeNode.questionVariantId)));
        expect(attempt.afterQuestionSha256).toBe(sha(current));
        expect(current.contentVersion).toBe(authored.I15_REVISION_DRAFT.contentVersion);
        expect(attempt.clinicalMeaningChanged).toBe(false);
      }
    }
    expect(count).toBe(35);
