      expect(sha(authored.I15_QUESTIONS.find(q => q.id === pin.questionVariantId))).toBe(pin.questionSha256);
      expect(sha(authored.I15_CONCEPTS.find(c => c.id === decisionNodes[0]!.primaryConceptId))).toBe(pin.conceptSha256);
      expect(authored.I15_ITEMS[0]).toEqual(round.reviewedSnapshot.I15_ITEMS[0]);
      expect(authored.I15_AUTHORING_CONCEPTS[0]).toEqual(round.reviewedSnapshot.I15_AUTHORING_CONCEPTS[0]);
      expect(authored.I15_AUTHOR_CHECKS[0]).toEqual(round.reviewedSnapshot.I15_AUTHOR_CHECKS[0]);
      expect(authored.I15_CASE_REVIEWS[0]).toEqual(round.reviewedSnapshot.I15_CASE_REVIEWS[0]);
      expect(authored.I15_STATEMENT_MAPPINGS[0]).toEqual(round.reviewedSnapshot.I15_STATEMENT_MAPPINGS[0]);
      expect(authored.I15_TIMING_ENTRIES[0]).toEqual(round.reviewedSnapshot.I15_TIMING_ENTRIES[0]);
      expect(authored.I15_PROCEDURE_CONTEXT_PROPOSALS[0]).toEqual(round.reviewedSnapshot.I15_PROCEDURE_CONTEXT_PROPOSALS[0]);
    }
    expect(authored.I15_SOURCES).toEqual(round.reviewedSnapshot.I15_SOURCES);
    expect(authored.I15_CLAIMS).toEqual(round.reviewedSnapshot.I15_CLAIMS);
  });

  it("keeps IDs stable while removing returned cues and retaining honest basic-purpose holds", () => {
    const old = packet.revisionRound1.reviewedSnapshot;
    expect(authored.I15_CASES.map(c => c.id)).toEqual(old.I15_CASES.map(c => c.id));
    expect(authored.I15_QUESTIONS.map(q => [q.id, q.conceptId])).toEqual(old.I15_QUESTIONS.map(q => [q.id, q.conceptId]));
    for (const q of old.I15_QUESTIONS) {
      const current = authored.I15_QUESTIONS.find(v => v.id === q.id)!;
      expect(current.answerChoices.map(a => a.id)).toEqual(q.answerChoices.map(a => a.id));
    }
    const retrieval = authored.I15_CASES[1]!;
    const r = retrieval.decisionNodes[0]!;
    expect(JSON.stringify([retrieval.presentation, r.currentUpdate, r.answerChoices.map(a => a.label)]))
      .not.toMatch(/in one piece|attached stalk|cautery end remain visible|Detach the stalk|Divide the head|irregular head/i);
    expect(r.stem).toContain("tissue-collection plan");
    expect(r.answerChoices.find(a => a.id.includes(".separate."))!.label).toContain("polypectomy-base biopsies");
    const marking = authored.I15_CASES[2]!;
    const m = marking.decisionNodes[0]!;
    expect(JSON.stringify([marking.presentation, m.currentUpdate])).not.toMatch(/32-mm|uniform granular|granular surface/i);
    expect(m.answerChoices.every(a => !/\d/.test(a.label) && a.label.includes("lesion"))).toBe(true);
    expect(m.answerChoices.find(a => a.isCorrect)!.label).toContain("distal to the lesion edge");
    for (const gate of authored.I15_AUTHOR_CHECKS.slice(1)) {
      expect(gate.difficulty).toMatch(/easy/i);
      expect(gate.recallException?.basicAccepted).toBe(false);
      expect(gate.pipelinePassed).toBe(false);
    }
  });

  it("keeps gameplay content offline and source links safe", () => {
    for (const link of authored.I15_SOURCE_LINKS) expect(link).toMatchObject({ target: "_blank", rel: "noopener noreferrer", referrerPolicy: "no-referrer" });
    const source = read("packages/clinical-content/src/question-intraop-suspicious-polyps-retrieval-and-tattoo-20261112.ts");
    expect(source).not.toMatch(/\bfetch\s*\(|XMLHttpRequest|https\.request|openai/i);
    expect(source).not.toMatch(/from\s+["']\.\/(?:index|synthetic-content|question-ship-manifest)["']/);
