import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { answerChoiceTimingRegistryEntrySchema, validateSyntheticClinicalRelease } from "./schema";
import * as authored from "./question-intraop-polypectomy-technique-and-bleeding-20261112";

const root = new URL("../../../", import.meta.url);
const read = (path: string) => readFileSync(new URL(path, root), "utf8");
const sha = (value: unknown) => createHash("sha256").update(typeof value === "string" ? value : JSON.stringify(value)).digest("hex");
const packetPath = "docs/research/question-intraop-polypectomy-technique-and-bleeding-20261112.json";
interface BeforeRow {
  recordId: string; inventoryKind: string; conceptId: string; questionVariantId: string;
  nodeId?: string; questionSha256?: string; nodeSha256?: string;
  source: { file: string; export: string };
  exactDefinition: unknown; currentDefinitionMatch: boolean;
  allSourceContexts: Array<{ headerSha256: string; header: unknown; precedingNodes: unknown[];
    origins: Array<{ file: string; export: string }> }>;
}
interface LintReport { variantId: string; caseId: string; profileId: string | null; findings: unknown[] }
const packet = JSON.parse(read(packetPath)) as {
  assignment: { id: string; slug: string; retainedRecordIds: string[]; authoringDefinitionRecordIds: string[];
    exactInventoryRecordIds: { live: string[]; retained: string[]; authoring: string[] } };
  before: BeforeRow[];
  audit: Array<{ recordId: string; verdict: string | null; planningDisposition: string | null; beforeSha256: string }>;
  counts: Record<string, unknown>;
  exportsSnapshot: Record<string, unknown>;
  freeze: { clinicalApprovals: Array<{ id: string; reviewer: string; approvedQuestionVariantIds: string[];
    questions: Array<{ questionVariantId: string; questionSha256: string }> }>; currentLive: unknown[] };
  reviewReferences: Array<{ path: string; fileSha256: string }>;
  cueLint: { version: string; contexts: number; variantCount: number; findings: unknown[]; suppressions: unknown[]; reports: LintReport[] };
  proposedItems: Array<{ nodeId: string; questionVariantId: string; exactAfterSha256: string; exactQuestionSha256: string }>;
  revisionRound1: {
    round: number;
    reviewInput: { path: string; sha256: string; records: Array<{ id: string; nodeId: string; verdict: string;
      clarityIssues: string[]; cues: Array<{ phrase: string; why: string }>; fairness: string[]; suggestions: string[] }> };
    reviewedSnapshot: { I14_CASES: typeof authored.I14_CASES; I14_QUESTIONS: typeof authored.I14_QUESTIONS;
      I14_ITEMS: typeof authored.I14_ITEMS; I14_CONCEPTS: typeof authored.I14_CONCEPTS };
    frozenPass: Array<{ questionVariantId: string; nodeId: string; caseId: string;
      questionSha256: string; nodeSha256: string; caseHeaderSha256: string }>;
    noteResponses: Array<{ questionVariantId: string; category: string; index: number; note: unknown; response: string; status: string }>;
    attempts: Array<{ questionVariantId: string; attemptCount: number; beforeQuestionSha256: string; afterQuestionSha256: string }>;
  };
};
const ledger = JSON.parse(read("docs/research/sources-question-intraop-polypectomy-technique-and-bleeding-20261112.json")) as {
  sources: typeof authored.I14_SOURCES; evidenceClaims: typeof authored.I14_CLAIMS;
  statementMappings: typeof authored.I14_STATEMENT_MAPPINGS;
  excludedSourceRecords: Array<{ evidenceClaimIds: string[]; reuseStatus: string }>;
  sourceUseRules: { fullTextStored: boolean; sourceExcerptsStored: boolean; gameplayNetwork: boolean };
};

function objects(value: unknown, seen = new Set<object>(), output: Record<string, unknown>[] = []) {
  if (!value || typeof value !== "object" || seen.has(value)) return output;
  seen.add(value);
  if (!Array.isArray(value)) output.push(value as Record<string, unknown>);
  for (const child of Object.values(value)) if (child && typeof child === "object") objects(child, seen, output);
  return output;
}

describe("I14 polypectomy technique and bleeding authoring sidecar", () => {
  it("audits the complete assigned identity inventory and separates returned planning records", () => {
    expect(packet.assignment).toMatchObject({ id: "I14", slug: "polypectomy-technique-and-bleeding" });
    expect(packet.before).toHaveLength(65);
    expect(new Set(packet.before.map(r => r.recordId)).size).toBe(65);
    for (const [kind, ids] of Object.entries(packet.assignment.exactInventoryRecordIds)) {
      const inventoryKind = kind === "live" ? "liveCoverage" : kind === "retained" ? "retainedCoverage" : "authoringDefinitions";
      expect(packet.before.filter(r => r.inventoryKind === inventoryKind).map(r => r.recordId)).toEqual(ids);
    }
    expect(packet.assignment.exactInventoryRecordIds.retained).toEqual(packet.assignment.retainedRecordIds);
    expect(packet.assignment.exactInventoryRecordIds.authoring).toEqual(packet.assignment.authoringDefinitionRecordIds);
    expect(packet.audit).toHaveLength(65);
